// Code Node #1: Calculate Value Tier & Approval Chain
const item = $input.first().json;
const value = item.contractValue;

if (value > 500000) {
  item.approvalLevels = 6;
  item.boardNotify = true;
} else if (value > 50000) {
  item.approvalLevels = 4;
  item.boardNotify = false;
} else {
  item.approvalLevels = 2;
  item.boardNotify = false;
}

return { json: item };

// Code Node #3: Complexity & Compression Prediction
const item = $input.first().json;
const pages = item.pageEstimate || 10;
const domain = item.clientEmail.split('@')[1];

// Decision Matrix for Compression
if (pages > 30) {
  item.compressionRatio = 0.65;
  item.deliveryMethod = 'drive_link';
} else if (domain === 'gmail.com') {
  item.compressionRatio = 0.85;
  item.limit = 25;
} else {
  item.compressionRatio = 0.90;
  item.limit = 20;
}

return { json: item };

// Code Node #4: Size Validation
const binary = $input.first().binary.data;
const limit = $input.first().json.limit || 25;
const sizeMB = binary.fileSize / 1024 / 1024;

return { 
  json: { 
    sizeExceeded: sizeMB > limit,
    finalSize: sizeMB.toFixed(2) + 'MB'
  }
};

// Code Node #9: Audit Trail Generator
const item = $input.first().json;
item.auditLog = `
  - Approved by: ${item.approvers.join(', ')}
  - Generated: ${new Date().toISOString()}
  - Final Size: ${item.finalSize}
  - Deliver Proof: ${item.deliveryTimestamp}
`;
return { json: item };

